create extension if not exists pgcrypto;
create type public.user_role as enum ('customer','organizer','admin');
create type public.account_status as enum ('active','suspended');
create table public.profiles(id uuid primary key references auth.users on delete cascade,full_name text not null,phone text,avatar_url text,role user_role not null default 'customer',status account_status not null default 'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.events(id uuid primary key default gen_random_uuid(),organizer_id uuid not null references public.profiles,title text not null,slug text unique not null,status text not null default 'draft',category text,city text,location text,online_url text,starts_at timestamptz,ends_at timestamptz,created_at timestamptz not null default now());
create table public.ticket_types(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events on delete cascade,name text not null,price numeric(14,2) not null check(price>=0),quota int not null check(quota>0),sold int not null default 0,min_purchase int not null default 1,max_purchase int not null default 5,sales_start timestamptz,sales_end timestamptz,is_active boolean not null default true);
create table public.orders(id uuid primary key default gen_random_uuid(),order_number text unique not null,user_id uuid not null references public.profiles,status text not null default 'pending',payment_status text not null default 'pending',subtotal numeric(14,2) not null,discount numeric(14,2) not null default 0,service_fee numeric(14,2) not null default 0,total numeric(14,2) not null,paid_at timestamptz,created_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders on delete cascade,ticket_type_id uuid not null references public.ticket_types,quantity int not null check(quantity>0),unit_price numeric(14,2) not null);
create table public.attendees(id uuid primary key default gen_random_uuid(),order_item_id uuid not null references public.order_items on delete cascade,full_name text not null,email text,phone text,identity_number text);
create table public.tickets(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders,user_id uuid not null references public.profiles,event_id uuid not null references public.events,ticket_type_id uuid not null references public.ticket_types,attendee_id uuid references public.attendees,code text unique not null,qr_value text unique not null,status text not null default 'active',checked_in_at timestamptz);
create table public.favorites(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles,event_id uuid not null references public.events,created_at timestamptz not null default now(),unique(user_id,event_id));
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles,title text not null,body text not null,target_url text,read_at timestamptz,created_at timestamptz not null default now());
create table public.vouchers(id uuid primary key default gen_random_uuid(),organizer_id uuid references public.profiles,event_id uuid references public.events,code text unique not null,discount_type text not null,discount_value numeric not null,minimum numeric not null default 0,max_discount numeric,quota int,used int not null default 0,per_user_limit int not null default 1,starts_at timestamptz,ends_at timestamptz,is_active boolean not null default true);
create table public.check_ins(id uuid primary key default gen_random_uuid(),ticket_id uuid not null references public.tickets,checked_in_by uuid not null references public.profiles,created_at timestamptz not null default now(),unique(ticket_id));
create table public.withdrawals(id uuid primary key default gen_random_uuid(),organizer_id uuid not null references public.profiles,amount numeric not null check(amount>0),bank_name text not null,account_number text not null,account_name text not null,status text not null default 'pending',created_at timestamptz not null default now());
create table public.refunds(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders,user_id uuid not null references public.profiles,amount numeric not null,status text not null default 'requested',reason text,reviewed_by uuid references public.profiles,created_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),admin_id uuid not null references public.profiles,action text not null,entity_type text not null,entity_id uuid,reason text,old_values jsonb,new_values jsonb,created_at timestamptz not null default now());
create or replace function public.has_role(required_role user_role) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role=required_role and status='active')$$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select public.has_role('admin')$$;
alter table profiles enable row level security;alter table events enable row level security;alter table ticket_types enable row level security;alter table orders enable row level security;alter table order_items enable row level security;alter table attendees enable row level security;alter table tickets enable row level security;alter table favorites enable row level security;alter table notifications enable row level security;alter table vouchers enable row level security;alter table check_ins enable row level security;alter table withdrawals enable row level security;alter table refunds enable row level security;alter table audit_logs enable row level security;
create policy profile_self on profiles for select using(id=auth.uid() or is_admin());
create policy profile_update_self on profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy published_events on events for select using(status='published' or organizer_id=auth.uid() or is_admin());
create policy organizer_events on events for all using(organizer_id=auth.uid() or is_admin()) with check(organizer_id=auth.uid() or is_admin());
create policy customer_orders on orders for select using(user_id=auth.uid() or is_admin());
create policy customer_order_items on order_items for select using(exists(select 1 from orders o where o.id=order_id and(o.user_id=auth.uid() or is_admin())));
create policy customer_attendees on attendees for select using(exists(select 1 from order_items oi join orders o on o.id=oi.order_id where oi.id=order_item_id and(o.user_id=auth.uid() or is_admin())));
create policy customer_tickets on tickets for select using(user_id=auth.uid() or is_admin() or exists(select 1 from events e where e.id=event_id and e.organizer_id=auth.uid()));
create policy own_favorites on favorites for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy own_notifications on notifications for select using(user_id=auth.uid() or is_admin());
create policy own_notification_update on notifications for update using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy organizer_withdrawals on withdrawals for select using(organizer_id=auth.uid() or is_admin());
create policy organizer_withdrawal_create on withdrawals for insert with check(organizer_id=auth.uid() and has_role('organizer'));
create policy admin_audit on audit_logs for select using(is_admin());
-- Orders, paid status, tickets, refunds, check-ins, and audit writes intentionally have no direct client write policy; use audited RPC/Edge Functions.
create or replace function public.check_in_ticket(target_event_id uuid,scanned_qr text) returns jsonb language plpgsql security definer set search_path=public as $$declare t tickets%rowtype;begin if not has_role('organizer') and not is_admin() then raise exception 'forbidden';end if;select * into t from tickets where qr_value=scanned_qr and event_id=target_event_id for update;if not found then raise exception 'ticket_not_found';end if;if t.status<>'active' then raise exception 'ticket_not_active';end if;if t.checked_in_at is not null then raise exception 'already_checked_in';end if;if not is_admin() and not exists(select 1 from events where id=target_event_id and organizer_id=auth.uid()) then raise exception 'wrong_event';end if;update tickets set checked_in_at=now(),status='checked_in' where id=t.id;insert into check_ins(ticket_id,checked_in_by)values(t.id,auth.uid()) on conflict(ticket_id)do nothing;return jsonb_build_object('status','valid','ticket_id',t.id);end$$;
create or replace function public.perform_admin_action(action_name text,target_type text,target_id uuid,action_reason text) returns uuid language plpgsql security definer set search_path=public as $$declare log_id uuid;begin if not is_admin() then raise exception 'forbidden';end if;if coalesce(trim(action_reason),'')='' then raise exception 'reason_required';end if;insert into audit_logs(admin_id,action,entity_type,entity_id,reason)values(auth.uid(),action_name,target_type,target_id,action_reason)returning id into log_id;return log_id;end$$;
